style.css:
@-moz-document domain("batcave.biz") {
/* ==========================================================
     1. HIGH-TECH TERMINAL VARIABLE SYSTEM
     ========================================================== */
  :root {
    /* Rich tech-blue palette overlaid across tactical gray foundations */
    --bg-panel: rgba(11, 15, 25, 0.85) !important;
    --bg-card: rgba(22, 29, 49, 0.75) !important;
    --border: #24355a !important;
    --text-primary: #f8fafc !important;
    --text-secondary: #94a3b8 !important;
    --accent: #facc15 !important; /* Bat-Signal Yellow */
    --glow: rgba(250, 204, 21, 0.25) !important;
  }

  /* ==========================================================
     2. THE BATCAVE BACKGROUND INJECTION
     ========================================================== */
  body, html, #page-wrapper, .main-content {
    /* Uses a high-quality atmospheric concept art wallpaper */
    background-image: linear-gradient(
        to bottom,
        rgba(11, 15, 25, 0.82), 
        rgba(15, 23, 42, 0.93)
      ), 
      url('https://wallpapers.com') !important;
    
    background-size: cover !important;
    background-position: center top !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
    color: var(--text-primary) !important;
  }

  /* ==========================================================
     3. INTERFACE ELEMENTS & CONTAINERS OVERRIDE
     ========================================================== */
  
  /* Translucent Frosted Glass Layering for Comic Cards */
  .comic-card, .manga-box, .card, .panel, .list-group-item {
    background-color: var(--bg-card) !important;
    border: 1px solid var(--border) !important;
    border-radius: 10px !important;
    /* Frosted glass layout effect to separate elements from the background image */
    backdrop-filter: blur(8px) webkit-backdrop-filter(8px) !important;
    transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.25s ease !important;
  }

  /* Interactive Hover Glow */
  .comic-card:hover, .manga-box:hover {
    border-color: var(--accent) !important;
    box-shadow: 0 8px 24px var(--glow) !important;
    transform: translateY(-4px) !important;
  }

  /* Headers, Sidebars, and Structural Bars */
  header, nav, .navbar, .sidebar, .top-bar {
    background-color: var(--bg-panel) !important;
    border-bottom: 1px solid var(--border) !important;
    backdrop-filter: blur(12px) webkit-backdrop-filter(12px) !important;
  }

  /* Typography & Core Navigation Anchors */
  h1, h2, h3, .title, .logo-text, strong {
    color: var(--text-primary) !important;
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5) !important;
  }

  a, .accent-text {
    color: var(--accent) !important;
  }

  p, .text-muted, .meta-data, .timestamp {
    color: var(--text-secondary) !important;
  }

  /* Action Buttons styling */
  .btn-primary, button, input[type="submit"] {
    background-color: var(--border) !important;
    color: var(--text-primary) !important;
    border: 1px solid rgba(255, 255, 255, 0.1) !important;
    border-radius: 6px !important;
    font-weight: 600 !important;
    text-transform: uppercase !important;
    letter-spacing: 0.05em !important;
    transition: background-color 0.2s ease, color 0.2s ease !important;
  }

  .comic-card:hover button, .btn-primary:hover {
    background-color: var(--accent) !important;
    color: #0b0f19 !important; /* Contrast text against the yellow highlight color */
    box-shadow: 0 0 10px rgba(250, 204, 21, 0.4) !important;
  }
}
